'use strict';

/**
* Apply a JSON Patch `add` operation to a document immutably.
*
* @module @stdlib/utils/json-patch/ops/add
*
* @example
* var add = require( '@stdlib/utils/json-patch/ops/add' );
*
* var doc = { 'foo': { 'bar': 1 } };
* var out = add( doc, '/foo/baz', 2 );
* // returns { 'foo': { 'bar': 1, 'baz': 2 } }
*/

// MODULES //

var main = require( './main.js' );


// EXPORTS //

module.exports = main;
